  const time = value => { const date = value ? new Date(typeof value==='number'&&value<1e12?value*1000:value) : new Date(); return Number.isNaN(+date) ? '时间未知' : date.toLocaleTimeString('zh-CN',{hour12:false}); };
  const routeSignature = () => JSON.stringify({targets:state.plan.targets,channels:state.plan.channels,dns_overrides:state.plan.dns_overrides});
