  function toast(message, error = false) { const node = $('#toast'); node.textContent = message; node.classList.toggle('error',error); node.hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => {node.hidden = true;}, error ? 7000 : 4200); }
  function activity(message, kind = '设计动作', detail = '') { state.activity.unshift({time:new Date().toISOString(),message,kind,detail}); state.activity = state.activity.slice(0,100); renderActivity(); }
  function persistLocal() { try { localStorage.setItem('flowdesk.plan.v1',JSON.stringify({plan:state.plan,dirty:state.dirty})); } catch (_) {} }
