      if(node.kind==='target'){const item=node.target,proxy=['http','socks5'].includes(item.type);return `<article class="graph-node target-node ${proxy?'proxy-target':item.type==='block'?'block-target':''}${selected}" data-node="${h(node.id)}" style="${style}"><button class="port-button input-port" data-target-input="${h(item.id)}" aria-label="连接到${h(targetName(item.id))}"></button><div class="node-title" tabindex="0" role="button" aria-label="编辑${h(targetName(item.id))}"><span class="mini-symbol ${proxy?'proxy':item.type}">${proxy?'⇄':item.type==='block'?'⊘':'↗'}</span><div class="node-title-copy"><h3>${h(targetName(item.id))}</h3><span class="node-kicker">${h(proxy?item.type.toUpperCase()+' 上游':item.type==='block'?'拒绝转发':'出口网卡 / 系统路由')}</span></div></div><div class="node-body"><span class="endpoint-label">${h(endpointText(item))}</span><span class="node-note">${proxy?'入口协议和目标连通需独立验证':item.type==='direct'?'DIRECT 不自动等于绕过 TUN':'仅作用于本中继收到的请求'}</span></div><div class="node-footer"><span>方案出口</span><span>预览后才运行</span></div></article>`;}
      if(node.kind==='context'&&node.category==='uu')return `<article class="graph-node${selected}" data-node="${node.id}" style="${style}"><div class="node-title" tabindex="0" role="button" aria-label="查看UU加速器独立加速层"><span class="app-symbol uu">U</span><div class="node-title-copy"><h3>UU 加速器</h3><span class="node-kicker">独立加速层 · 只读上下文</span></div></div><div class="node-body">不作为 HTTP / SOCKS 出口。<br><span class="node-note">加速与系统代理、hosts 影响需分开核对。</span></div></article>`;
