      const progress=(e.stage==='established'||e.status==='connected'||e.status==='established')?'路径已建立 / 进行中（未证明应用会话）':e.status||'已记录';
      const route=`通道 ${channel_id||'未知'} → 出口 ${target_id||'未知'} · ${e.rule_id?'规则 '+e.rule_id:target_id?'默认出口':'未记录命中规则'}`;
