    (state.snapshot?.findings||[]).forEach(item=>grid.insertAdjacentHTML('beforeend',card(item.title||'本机发现',item.severity==='error'?'failed':item.evidence_status||'observed',item.detail||item.message||'')));
    const changes=state.snapshot?.changes_since_previous;const value=v=>String(typeof v==='string'?v:(JSON.stringify(v)??'未记录')).replace(/\/\/[^/@\s]+@/g,'//[凭据已隐藏]@').slice(0,210);
