  function previewItems(value, kind) {const list=Array.isArray(value)?value:value?[value]:[];return list.map(item=>{const text=typeof item==='string'?item:item.message||item.detail||item.reason||item.title||JSON.stringify(item);return`<div class="preview-item ${kind}">${icon(kind==='blocker'?'close':kind==='warning'?'info':'check')}<div><p>${h(text)}</p></div></div>`;}).join('');}
  async function preview() {$('#preview-start-button').hidden=false;await task($('#preview-button'),async()=>{const report=await api('/api/preview','POST',{plan:state.plan});state.preview=report;state.previewSignature=routeSignature();const issueList=Array.isArray(report.issues)?report.issues:[];const errors=report.blockers||report.errors||issueList.filter(i=>['error','blocker','fatal'].includes(i.severity)),warnings=report.warnings||report.limitations||issueList.filter(i=>!['error','blocker','fatal'].includes(i.severity)),canStart=report.can_start===true||report.valid===true||report.ok===true;const blocked=report.can_start===false||report.valid===false||report.ok===false||(Array.isArray(errors)&&errors.length>0);$('#preview-content').innerHTML=`<div class="notice"><strong>本次仅准备本地中继入口。</strong><br>不重启 Codex，不自动修改应用配置、系统代理、TUN、路由或 DNS。实际应用需接入并独立验证。</div><section class="preview-section"><h3>方案内容</h3><ul class="preview-list"><li>${state.plan.channels.length} 个应用通道，${state.plan.targets.length} 个出口，${state.plan.channels.reduce((sum,c)=>sum+c.rules.length,0)} 条域名规则。</li><li>${Object.keys(state.plan.dns_overrides||{}).length} 项显式解析映射，仅作用本中继；保留原 HTTP Host / TLS 域名。</li><li>本地监听地址与端口以启动返回为准，不是系统或任意进程的透明接管。</li></ul></section>${errors.length?`<section class="preview-section"><h3>需要先处理</h3>${previewItems(errors,'blocker')}</section>`:''}<section class="preview-section"><h3>能力与待验证事项</h3>${previewItems(warnings,'warning')}${!warnings.length?'<p class="field-note">后端没有返回额外警告；这不代表真实应用已验证。</p>':''}${report.notice?`<p class="field-note">${h(report.notice)}</p>`:''}</section>${!canStart&&!blocked?'<div class="notice danger">服务未返回明确的可启动结论，当前不能启动。</div>':''}`;$('#preview-start-button').disabled=blocked||!canStart||state.runtime.running;$('#preview-dialog').showModal();activity('已生成方案影响预览，尚未改变应用或系统网络。');});}
  async function start() {await task($('#preview-start-button'),async()=>{if(state.previewSignature!==routeSignature())throw new Error('方案已变化，请重新预览。');const data=await api('/api/runtime/start','POST',{plan:state.plan});ingest(data);state.runtimeSignature=routeSignature();$('#preview-dialog').close();await refresh(false);switchDock('runtime');activity('本地中继启动请求完成；入口监听与真实应用接入分开验证。','中继状态');toast('本地入口已返回，复制实际入口后显式配置应用。');});renderGraph();renderInspector();}
