  function download(filename,content,mime='application/json') {const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function exportData(kind) {if(!state.connected&&kind==='plan'){download('流向-方案.json',JSON.stringify(state.plan,null,2));toast('已导出离线设计方案。');return;}await task(kind==='plan'?$('#export-button'):$('#diagnostic-export-button'),async()=>{const data=await api('/api/export','POST',kind==='plan'?{kind,plan:state.plan}:{kind});if(typeof data.content!=='string')throw new Error('后端没有返回可下载的导出内容。');download(data.filename||`flowdesk-${kind}.json`,data.content,data.mime);activity(kind==='plan'?'方案 JSON 已导出。':'后端脱敏诊断已导出；不包含认证或订阅配置。');});}
