  async function probe() {const input=$('#probe-target');if(!input?.value.trim())return toast('先填写一个有界探测 URL。',true);await task($('#probe-button'),async()=>{const selected=state.selected,body={url:input.value.trim(),mode:$('#probe-mode')?.value||'http',...(selected.kind==='target'?{target_id:selected.id,plan:state.plan}:{channel_id:selected.id})};const result=await api('/api/probe','POST',body);state.probeLayers=result.layers||[];state.probeScope=result.scope||'';const summary=state.probeLayers.map(l=>`${l.layer}: ${l.status}`).join(' / ');activity(`探测返回：${summary}；${result.scope||'仅此探测，不代表真实应用已接入'}。`,'探测证据');$('#preview-content').innerHTML=`<div class="notice">${h(result.scope||'此探测不代表真实应用已接入。')}<br>真实应用：${h(result.application||'unknown')}；持续连接：${h(result.long_lived_connection||'未测试')}</div>${previewItems(state.probeLayers.map(l=>({message:`${l.layer} · ${l.status}${l.http_status?' · HTTP '+l.http_status:''}${l.elapsed_ms!==undefined?' · '+l.elapsed_ms+' ms':''}${l.message?' · '+l.message:''}${l.meaning?' · '+l.meaning:''}`})),'')}`;$('#preview-start-button').hidden=true;$('#preview-dialog').showModal();renderEvidence();switchDock('activity');});}
  async function resolve() {const input=$('#resolve-host'),host=input?.value.trim();if(!host)return toast('先输入精确域名。',true);await task($('#resolve-button'),async()=>{const result=await api('/api/resolve','POST',{host});const addresses=(result.addresses||[]).map(a=>typeof a==='string'?a:a.address||a.ip).filter(Boolean);$('#resolve-result').innerHTML=`<strong>${h(result.status||'已返回')}</strong><br>系统解析：${h(addresses.join('、')||'没有返回地址')}<br>hosts 条目：${h((result.hosts_entries||[]).join('、')||'无匹配条目')}<br>${h(result.notice||'本次仅为解析观察。')}${addresses.length?`<br><button class="text-button" data-add-dns-host="${h(host)}" data-add-dns-ip="${h(addresses[0])}">将首个地址显式加入本方案</button>`:''}`;activity(`域名解析观察：${host} → ${addresses.join('、')||'无地址'}；未修改系统 hosts。`,'本机观察');});}
  async function systemPreview() {
    await task($('#system-preview-button'),async()=>{
      const channel_id=$('#system-channel').value;
      if(!channel_id)throw new Error('先选择已运行的本地通道。');
      const result=await api('/api/system/preview','POST',{channel_id});
      state.systemPreview={...result,channel_id};
      const before=result.before||{},after=result.after||{};
      const rules=(result.rules||[]).map(r=>`<p class="field-note">${h((r.domains||[]).join('、'))} → ${h(targetName(r.target))}</p>`).join('');
      const mappings=Object.entries(result.dns_overrides||{}).map(([host,ip])=>`<p class="field-note"><code>${h(host)}</code> → <code>${h(ip)}</code></p>`).join('');
      $('#system-preview-content').innerHTML=`<div class="notice danger"><strong>这是单独的系统设置变更。</strong><br>修改当前用户 WinINet，例外规则与解析映射影响所有使用该入口的应用，无法按进程区分。既有应用是否采用新设置仍需验证。</div><section class="preview-section"><h3>变更前 → 变更后</h3><dl class="support-facts"><dt>原标志</dt><dd>${h(before.flags??'未知')}</dd><dt>原代理</dt><dd>${h(before.server||'未配置静态代理')}</dd><dt>新标志</dt><dd>${h(after.flags??'未知')}</dd><dt>新代理</dt><dd>${h(after.server||'未返回')}</dd></dl></section><section class="preview-section"><h3>${result.allowed===true?'允许应用的范围':'目前不能应用'}</h3>${previewItems(result.issues||[],'warning')}<p class="field-note">${h(result.notice||'试用60秒，未确认会尝试回退。')}</p><h3>会影响系统入口的域名规则</h3>${rules||'<p class="field-note">无例外规则，仅默认出口。</p>'}<h3>会作用于系统入口的解析映射</h3>${mappings||'<p class="field-note">没有显式解析映射。</p>'}<p class="field-note">映射保留原 HTTP Host / TLS 域名，不改系统 hosts；使用这个系统入口的其他应用也会受影响。</p></section>${result.allowed===true?'<label class="preview-confirm"><input id="system-consent" type="checkbox"><span>已核对范围；只应用本次预览，未确认时恢复原系统代理。</span></label>':'<div class="notice danger">后端未允许此变更，复选框无法解锁应用。</div>'}`;
      $('#system-apply-button').disabled=true;
      $('#system-dialog').showModal();
    });
  }
  async function systemApply() {await task($('#system-apply-button'),async()=>{if(state.systemPreview?.allowed!==true||!$('#system-consent')?.checked)throw new Error('请先阅读并确认本次系统接入范围。');const p=state.systemPreview;if(!p?.preview_id)throw new Error('系统预览缺少 preview_id，不能应用。');await api('/api/system/apply','POST',{channel_id:p.channel_id,preview_id:p.preview_id});$('#system-dialog').close();await refresh(false);activity('已显式请求系统接入，等待有界确认；本地入口监听不代表应用连接正常。','系统变更');toast('请实际验证连接，再确认保留；不确认由后端回退。');});}
